/* =========================================================================
   NIFTY WEBSITES AUSTRALIA - SITE FOOTER
   Pure CSS. Nothing here depends on scripting, so the footer survives an
   importer that removes it.
   ========================================================================= */

.site-footer{
  --amber:#f7a80a; --amber-l:#ffc247; --amber-d:#c47a08;
  --green:#34e0a1;
  --ink:#f4f6fb; --ink2:#c9cfdd; --mut:#8b93a8;
  --line:rgba(255,255,255,.10); --line2:rgba(255,255,255,.18);
  --glass:rgba(255,255,255,.045); --glass2:rgba(255,255,255,.08);
  --fdisp:'Sora',system-ui,-apple-system,'Segoe UI',sans-serif;
  --fbody:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;
  --r-pill:999px;
  --gut:clamp(18px,5vw,44px); --maxw:1240px;
  --logo:url('data:image/png;base64,');

  background:#05060c;border-top:1px solid var(--line);
  padding:64px 0 0;color:var(--ink2);
  font-family:var(--fbody);font-size:16.5px;line-height:1.62;
}
.site-footer *,.site-footer *::before,.site-footer *::after{box-sizing:border-box}
/* Element resets are wrapped in :where() so they carry ZERO specificity and can
   never outrank a component rule further down. Written plainly as
   `.site-footer ul {margin:0}` they score 0,1,1 and silently beat a class rule
   like `.ftr-contact {margin-top:38px}` at 0,1,0, which is exactly how the
   spacing in this column got flattened the first time round. */
:where(.site-footer) :where(ul,ol){list-style:none;margin:0;padding:0}
:where(.site-footer) :where(a){color:inherit;text-decoration:none}
:where(.site-footer) :where(p){margin:0}
.site-footer :focus-visible{outline:3px solid var(--amber-l);outline-offset:2px;border-radius:4px}
.site-footer .ico{width:1em;height:1em;flex:0 0 auto;fill:none;stroke:currentColor;
  stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.site-footer .ico-fill{fill:currentColor;stroke:none}
.site-footer .fillme{fill:currentColor;stroke:none}
.site-footer [data-not-in-build]{cursor:not-allowed}
.site-footer [data-not-in-build]::after{content:" \2197";opacity:.5;font-size:.85em}

.site-footer .wrap{max-width:var(--maxw);margin:0 auto;
  padding-left:var(--gut);padding-right:var(--gut)}

/* ------------------------------------------------------------ the columns */
.ftr-grid{display:grid;grid-template-columns:1.7fr repeat(5,minmax(0,1fr));gap:40px 26px}
@media(max-width:1180px){
  .ftr-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ftr-brandcol{grid-column:1 / -1;max-width:520px}
}
@media(max-width:700px){.ftr-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:460px){.ftr-grid{grid-template-columns:1fr}}

.ftr-col h4{font-family:var(--fdisp);font-size:11px;letter-spacing:.16em;
  text-transform:uppercase;color:var(--amber);margin:0 0 16px;font-weight:700;line-height:1.08}
.ftr-col li{margin:0 0 11px}
.ftr-col a{font-size:14.5px;color:var(--ink2);transition:color .15s}
.ftr-col a:hover{color:var(--amber-l)}
.ftr-col a strong{font-weight:600;color:var(--ink)}
.ftr-col + .ftr-sub{margin-top:24px}

/* ------------------------------------------------------- the brand column */
.ftr-logo{display:inline-block}
.ftr-logo .logoimg{background:var(--logo) center/contain no-repeat;display:block;
  height:78px;width:auto;aspect-ratio:372/114}
@media(max-width:520px){.ftr-logo .logoimg{height:58px}}
.ftr-blurb{font-size:14.8px;line-height:1.7;color:var(--mut);margin:22px 0 0;max-width:34ch}

.ftr-contact{margin:38px 0 0;display:grid;gap:18px}
.ftr-contact li{display:flex;align-items:flex-start;gap:12px;margin:0;font-size:14.8px}
.ftr-contact .ci{width:22px;height:22px;flex:0 0 auto;display:grid;place-items:center;
  color:var(--amber);font-size:15px;line-height:1;margin-top:1px}
.ftr-contact .ci .ico{width:16px;height:16px}
/* Drawn rather than an emoji: Windows has no flag glyphs and renders the
   regional-indicator pair as the bare letters "AU". */
.ftr-contact .auflag{width:22px;height:15px;border-radius:2px;flex:0 0 auto;display:block;
  box-shadow:0 0 0 1px rgba(255,255,255,.14)}
.ftr-contact .strongline{font-family:var(--fdisp);font-weight:700;font-size:15.5px;
  color:var(--ink);letter-spacing:-.01em}
.ftr-contact a.strongline:hover{color:var(--amber-l)}
.ftr-contact .softline{color:var(--mut);line-height:1.6}
.ftr-contact .softline strong{color:var(--ink2);font-weight:600}

/* Live status pill, carried over from the previous footer design. */
.ftr-live{display:inline-flex;align-items:center;gap:10px;margin-top:24px;
  padding:9px 18px 9px 14px;border-radius:var(--r-pill);
  border:1px solid rgba(52,224,161,.45);background:rgba(52,224,161,.07);
  font-family:var(--fdisp);font-weight:700;font-size:14px;color:var(--ink);
  letter-spacing:-.01em}
.ftr-live .dot{width:9px;height:9px;border-radius:50%;background:var(--green);
  flex:0 0 auto;box-shadow:0 0 0 0 rgba(52,224,161,.55);animation:ftrPulse 2.4s infinite}
@keyframes ftrPulse{
  0%{box-shadow:0 0 0 0 rgba(52,224,161,.55)}
  70%{box-shadow:0 0 0 8px rgba(52,224,161,0)}
  100%{box-shadow:0 0 0 0 rgba(52,224,161,0)}
}

.socials{display:flex;gap:10px;margin-top:24px}
.socials a{width:42px;height:42px;border-radius:12px;background:var(--glass);
  border:1px solid var(--line2);display:grid;place-items:center;color:var(--ink2);
  font-size:17px;transition:color .15s,border-color .15s,background .15s,transform .15s}
.socials a:hover{color:var(--amber);border-color:rgba(247,168,10,.5);
  background:var(--glass2);transform:translateY(-2px)}

/* ---------------------------------------------------------- the bottom bar */
.ftr-bottom{margin-top:56px;border-top:1px solid var(--line);padding:24px 0 34px;
  display:flex;align-items:center;justify-content:space-between;gap:16px 28px;
  flex-wrap:wrap;font-size:13.5px;color:var(--mut)}
.ftr-btm-left{display:flex;align-items:center;gap:10px 22px;flex-wrap:wrap}
.ftr-legal{display:flex;gap:20px;flex-wrap:wrap}
.ftr-legal a{color:var(--mut);transition:color .15s}
.ftr-legal a:hover{color:var(--amber-l)}

.built{display:inline-flex;align-items:center;gap:9px;font-size:13.5px;color:var(--ink2);
  white-space:nowrap}
.built-ico{width:24px;height:24px;flex:0 0 auto;display:block;object-fit:contain}
.built b{font-family:var(--fdisp);font-weight:700;letter-spacing:-.01em;color:var(--amber)}
/* Same gold gradient the wordmark carries in the reference. The flat amber
   above stays as the fallback for anything without background-clip:text. */
@supports ((-webkit-background-clip:text) or (background-clip:text)){
  .built b{background:linear-gradient(180deg,#ffd874 0%,#ffc247 42%,#f7a80a 100%);
    -webkit-background-clip:text;background-clip:text;color:transparent}
}

@media(prefers-reduced-motion:reduce){
  .site-footer *,.site-footer *::before,.site-footer *::after{
    transition-duration:.001ms!important;animation-duration:.001ms!important;
    animation-iteration-count:1!important}
}
